use super::*;
use semio_framework_os_spr::{MutationReplayOutcome,MutationId};
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096}}
fn source(case:&serde_json::Value)->ReplayReport{let mut outcomes=Vec::new();for repeat in 0..case["repeat"].as_u64().unwrap(){for row in case["outcomes"].as_array().unwrap(){let messages=row["messages"].as_array().unwrap().iter().enumerate().map(|(index,text)|{let mut text=format!("{}:{repeat}:{index}",text.as_str().unwrap());let wide=case["wideBytes"].as_u64().unwrap()as usize;if text.len()<wide{text.extend(std::iter::repeat_n('x',wide-text.len()));}let mut message=MutationMessage::warning("native.receipt",text);message.target=vec![format!("target-{repeat}-{index}")];message.op_index=Some(index as u32);message}).collect::<Vec<_>>();outcomes.push(MutationReplayOutcome{mutation_id:MutationId(format!("op-{}",outcomes.len())),edit_id:row["edit"].as_str().unwrap().into(),op_index:outcomes.len()as u32,worst:(!messages.is_empty()).then_some(semio_framework_diagnostic::Severity::Warning),messages,superseded:true,withdrawn:false});}}ReplayReport{from_position:0,worst:outcomes.iter().filter_map(|row|row.worst).max(),outcomes}}
fn exact(p:RetainedCloneProgress,heap:semio_framework_trace::HeapAllocationObservation){assert!(p.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn close_value<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut input=Some(value);let mut owner=RetainedCloneClose::default();for index in 0..1048576{if input.is_none()&&owner.is_empty(){break}let d=if input.is_some(){owner.next_owner_demands::<T>(true,&None,4096).unwrap()}else{RetirementDemand{copy_bytes:owner.next_copy_byte_demand().unwrap(),capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()}};assert!(d.copy_bytes<=4096);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||if input.is_some(){owner.begin_granted(&mut input,grant()).unwrap().unwrap()}else{owner.step_granted(grant()).unwrap()});exact(result.progress(),heap);assert!(index<1048575);}}
#[test]
fn original_replay_pending_receipt_groups_actual_messages_without_payload_clone_and_closes_every_prefix(){
 let f:serde_json::Value=serde_json::from_str(include_str!("fixture.json")).unwrap();for case in f["cases"].as_array().unwrap(){let cuts=f["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain(std::iter::once(None));for cut in cuts{let mut source=source(case);let pointers=source.outcomes.iter().flat_map(|row|row.messages.iter().map(|message|(message.message.as_ptr(),message.target.as_ptr()))).collect::<Vec<_>>();let mut expected:Vec<EditMessages>=Vec::new();for row in source.outcomes.iter().filter(|row|!row.messages.is_empty()){match expected.last_mut(){Some(group)if group.edit_id==row.edit_id=>group.messages.extend(row.messages.iter().cloned()),_=>expected.push(EditMessages{edit_id:row.edit_id.clone(),messages:row.messages.clone()})}}let mut owner=OriginalReplayPendingReport::default();for step in 0..1048576{if owner.prepared()||cut==Some(step){break}let d=owner.demands(&source).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=16<<20);for axis in 0..5{let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut denied=grant();match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=amount-1,2=>denied.maximum_capacity_bytes=amount-1,3=>denied.maximum_release_bytes=amount-1,_=>denied.maximum_depth=amount-1};let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut source,31,denied,|_|panic!("denied receipt cannot admit storage")).unwrap());exact(p,heap);assert_eq!(p,Default::default());}let mut admitted=0;let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut source,31,grant(),|bytes|{admitted+=bytes;Ok(())}).unwrap());exact(p,heap);assert_eq!(admitted,p.retained_capacity_bytes);assert!(step<1048575);}
 if cut.is_none(){assert!(owner.prepared());let report=owner.report.as_ref().unwrap();assert_eq!(report.messages,expected);assert_eq!(report.messages.len(),case["expectedGroups"].as_u64().unwrap()as usize);assert_eq!(report.messages.iter().map(|row|row.messages.len()).sum::<usize>(),case["expectedMessages"].as_u64().unwrap()as usize);assert_eq!(report.messages.iter().flat_map(|row|row.messages.iter().map(|message|(message.message.as_ptr(),message.target.as_ptr()))).collect::<Vec<_>>(),pointers);assert_eq!(report.worst,source.worst);assert_eq!(report.edit_ids,Some(Vec::new()));assert!(report.outbound.is_empty());assert!(source.outcomes.iter().all(|row|row.messages.is_empty()));}
 if owner.source.is_some(){let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&mut source,32,grant(),|_|Ok(())));assert!(p.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 for index in 0..1048576{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=16<<20);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant()).unwrap());exact(result.progress(),heap);assert!(index<1048575);}assert!(owner.terminal_is_empty());close_value(source);}}
}
